// Run with: node tests/analytics-notifications.test.mjs
// Checks the new Today / WTD / Week-by-week ranges, the weekly contribution reminder logic,
// and that the page's inline scripts still compile and the reminder block never touches the network or sheet.
// (First draft generated by local Ollama, reviewed and corrected by Claude.)
import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const here = path.dirname(fileURLToPath(import.meta.url));
const html = fs.readFileSync(path.join(here, '..', 'index.html'), 'utf8');
let passed = 0;
function test(name, fn) { try { fn(); passed++; console.log('ok - ' + name); } catch (e) { console.error('FAIL - ' + name + '\n' + e.message); process.exitCode = 1; } }
const ymd = d => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');

// ---------- PART 1: notification core ----------
const a = html.indexOf('/* NOTIF-CORE-START */'), b = html.indexOf('/* NOTIF-CORE-END */');
assert.ok(a >= 0 && b > a, 'notification core markers missing');
const core = html.slice(a, b);
const N = vm.runInNewContext(core + '\n;({NOTIF_DEFAULTS,notifNormalize,notifWeekKey,notifDue})', {});
// objects from the vm realm have a different prototype, so compare as JSON
const J = x => JSON.stringify(x);

test('notifNormalize falls back to Thursday 17:00 defaults', () => {
  assert.strictEqual(J(N.notifNormalize(null)), J({ enabled: false, day: 4, time: '17:00' }));
  assert.strictEqual(J(N.notifNormalize({ enabled: true, day: 9, time: '25:99' })), J({ enabled: true, day: 4, time: '17:00' }));
  assert.strictEqual(N.notifNormalize({ enabled: 'yes' }).enabled, false);
  assert.strictEqual(J(N.notifNormalize({ enabled: true, day: 2, time: '08:30' })), J({ enabled: true, day: 2, time: '08:30' }));
});

test('notifWeekKey returns the Monday, across month and year boundaries', () => {
  assert.strictEqual(N.notifWeekKey(new Date(2026, 9, 22, 12, 0)), '2026-10-19');
  assert.strictEqual(N.notifWeekKey(new Date(2026, 9, 25, 9, 0)), '2026-10-19'); // Sunday
  assert.strictEqual(N.notifWeekKey(new Date(2026, 10, 1, 9, 0)), '2026-10-26'); // Sun 1 Nov
  assert.strictEqual(N.notifWeekKey(new Date(2026, 0, 1, 9, 0)), '2025-12-29');  // Thu 1 Jan
});

test('notifDue fires from Thursday 5:00 PM through Sunday, once per week', () => {
  const cfg = { enabled: true, day: 4, time: '17:00' }; // 22 Oct 2026 is a Thursday
  assert.strictEqual(N.notifDue(cfg, new Date(2026, 9, 21, 23, 0), '', ''), false);
  assert.strictEqual(N.notifDue(cfg, new Date(2026, 9, 22, 16, 59), '', ''), false);
  assert.strictEqual(N.notifDue(cfg, new Date(2026, 9, 22, 17, 0), '', ''), true);
  assert.strictEqual(N.notifDue(cfg, new Date(2026, 9, 23, 8, 0), '', ''), true);
  assert.strictEqual(N.notifDue(cfg, new Date(2026, 9, 25, 20, 0), '', ''), true);
  assert.strictEqual(N.notifDue(cfg, new Date(2026, 9, 26, 8, 0), '', ''), false); // next Monday
  assert.strictEqual(N.notifDue({ ...cfg, enabled: false }, new Date(2026, 9, 22, 18, 0), '', ''), false);
  assert.strictEqual(N.notifDue(cfg, new Date(2026, 9, 22, 18, 0), '', '2026-10-19'), false); // dismissed this week
  assert.strictEqual(N.notifDue(cfg, new Date(2026, 9, 22, 18, 0), '', '2026-10-12'), true);  // dismissed last week
});

// ---------- PART 2: ranges ----------
const s = html.indexOf('function resolveRange(S){'), e = html.indexOf('const inR=');
assert.ok(s >= 0 && e > s, 'resolveRange not found');
const ctx = {
  addD: (d, n) => { const x = new Date(d.getFullYear(), d.getMonth(), d.getDate()); x.setDate(x.getDate() + n); return x; },
  diffD: (x, y) => Math.round((y - x) / 86400000),
  pd: s => s ? new Date(s + 'T00:00:00') : null,
  TODAY: new Date(2026, 9, 22), // Thursday
  store: { D: { expenses: [], items: [] } }
};
const resolveRange = vm.runInNewContext(html.slice(s, e) + '\n;resolveRange', ctx);

test('range today = one day, compared with yesterday', () => {
  const r = resolveRange({ range: 'today' });
  assert.strictEqual(r.len, 1);
  assert.strictEqual(ymd(r.start), '2026-10-22');
  assert.strictEqual(ymd(r.end), '2026-10-22');
  assert.strictEqual(ymd(r.pStart), '2026-10-21');
  assert.strictEqual(ymd(r.pEnd), '2026-10-21');
});
test('range wtd = Monday through today', () => {
  const r = resolveRange({ range: 'wtd' });
  assert.strictEqual(r.len, 4);
  assert.strictEqual(ymd(r.start), '2026-10-19');
  assert.strictEqual(ymd(r.end), '2026-10-22');
});
test('range wbw = 12 Monday-based weeks ending today', () => {
  const r = resolveRange({ range: 'wbw' });
  assert.strictEqual(ymd(r.start), '2026-08-03');
  assert.strictEqual(ymd(r.end), '2026-10-22');
  assert.strictEqual(r.start.getDay(), 1);
  assert.strictEqual(r.len, 81);
});
test('existing ranges are unchanged', () => {
  assert.strictEqual(resolveRange({ range: '30d' }).len, 30);
  assert.strictEqual(resolveRange({ range: '90d' }).len, 90);
  assert.strictEqual(ymd(resolveRange({ range: 'ytd' }).start), '2026-01-01');
  assert.strictEqual(resolveRange({ range: '12m' }).len, 365);
  assert.strictEqual(ymd(resolveRange({ range: 'month' }).start), '2026-10-01');
});
test('unknown range key falls back to 90 days', () => {
  assert.strictEqual(resolveRange({ range: 'bogus' }).len, 90);
});
test('range chips include the three new buttons', () => {
  const m = html.match(/const RANGES=(\[\[.*?\]\]);/);
  assert.ok(m, 'RANGES not found');
  const R = vm.runInNewContext(m[1], {});
  const keys = R.map(x => x[0]);
  for (const k of ['today', 'wtd', 'wbw', '30d', '90d', 'ytd', '12m', 'all', 'custom']) assert.ok(keys.includes(k), 'missing chip ' + k);
});

// ---------- PART 3: page integrity ----------
let n = 0;
const re = /<script(?![^>]*\bsrc=)[^>]*>([\s\S]*?)<\/script>/g;
let m;
while ((m = re.exec(html)) !== null) {
  n++;
  const code = m[1];
  test('inline script #' + n + ' compiles', () => { new vm.Script(code); });
}
test('reminder block present and never touches the network or sheet', () => {
  const r1 = html.indexOf('WEEKLY CONTRIBUTION REMINDER'), r2 = html.indexOf('setTimeout(()=>flush(true),2500);');
  assert.ok(r1 >= 0 && r2 > r1);
  const blk = html.slice(r1, r2);
  assert.ok(!/fetch\(|XMLHttpRequest|new Notification|serviceWorker|eval\(|document\.write|innerHTML\s*\+=|body\.innerHTML/.test(blk));
});

console.log(passed + ' tests passed');
